export const CENTER = {lat:38.5714,lon:-7.9086};
export function validCoordinate(p){return Number.isFinite(p.lat)&&Number.isFinite(p.lon)&&Math.abs(p.lat)<=90&&Math.abs(p.lon)<=180;}
export function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
export function haversine(a,b){const r=x=>x*Math.PI/180;const dlat=r(b.lat-a.lat),dlon=r(b.lon-a.lon);return 6371*2*Math.asin(Math.sqrt(Math.sin(dlat/2)**2+Math.cos(r(a.lat))*Math.cos(r(b.lat))*Math.sin(dlon/2)**2));}
export function canRoute(p,demo=false){if(!validCoordinate(p)||p.status==='unavailable')return false;if(p.demo)return demo;if(p.kind!=='water'&&p.kind!=='partner')return true;return p.potable===true&&p.free===true&&p.accessConfirmed===true&&p.operational===true&&!!p.checkedAt&&p.status==='checked'&&(p.kind!=='partner'||p.optIn===true);}
export function normalizeOSM(element){const tags=element.tags||{};const lat=element.lat??element.center?.lat,lon=element.lon??element.center?.lon;let kind=tags.shop==='supermarket'?'grocery':tags.amenity==='drinking_water'||tags.drinking_water==='yes'?'water':null;if(!kind||!validCoordinate({lat,lon}))return null;return {id:`osm-${element.type}-${element.id}`,name:tags.name||tags.brand||(kind==='water'?'Mapped drinking-water candidate':'Mapped grocery'),lat,lon,kind,demo:false,status:'candidate',potable:null,free:null,accessConfirmed:false,operational:null,optIn:false,checkedAt:null,opening:tags.opening_hours||'Opening hours unknown',access:tags.access||'Access unconfirmed',source:`https://www.openstreetmap.org/${element.type}/${element.id}`,sourceLabel:'OpenStreetMap · unverified',osmTags:{drinking_water:tags.drinking_water,fee:tags.fee,access:tags.access}};}
export function mapsURL(origin,stops){if(!validCoordinate(origin)||!stops.length||stops.some(p=>!validCoordinate(p)))throw Error('Choose valid route coordinates.');if(stops.length>4)throw Error('Split this route into mobile-friendly parts.');const q=new URLSearchParams({api:'1',origin:`${origin.lat},${origin.lon}`,destination:`${stops.at(-1).lat},${stops.at(-1).lon}`,travelmode:'walking'});if(stops.length>1)q.set('waypoints',stops.slice(0,-1).map(p=>`${p.lat},${p.lon}`).join('|'));return `https://www.google.com/maps/dir/?${q}`;}
export function routeParts(origin,stops){const parts=[];let start=origin;for(let i=0;i<stops.length;i+=4){const points=stops.slice(i,i+4);parts.push({origin:start,stops:points,url:mapsURL(start,points)});start=points.at(-1);}return parts;}
export function planOrder(origin,stops,mode='direct'){if(mode==='manual')return [...stops];let left=[...stops],result=[],current=origin;while(left.length){let best=0,score=Infinity;left.forEach((p,i)=>{const d=haversine(current,p);const s=mode==='discover'?d-(p.kind==='sight'?0.15:0):d;if(s<score){score=s;best=i;}});const next=left.splice(best,1)[0];result.push(next);current=next;}return result;}
